on conflict (external_key) do update set
 name=excluded.name,category=excluded.category,description=excluded.description,
 municipality_id=excluded.municipality_id,parish=excluded.parish,address=excluded.address,
 phone=excluded.phone,source_id=excluded.source_id,source_url=excluded.source_url,
 verification_status=excluded.verification_status,last_verified_at=excluded.last_verified_at,
 is_active=excluded.is_active,updated_at=now();

update public.island_sources
set update_note='Official Madeira tourism board directory of registered tourist-entertainment operators. MADEIRA AI imported source-listed records for Calheta and Ponta do Sol; listing is not independent proof of current operation or availability.',
last_checked_at=now(),is_active=true
where id='visit-madeira';
update public.island_sources
set update_note='Official municipal business directory covering Ponta do Sol, Canhas and Madalena do Mar. The public directory lists sectors and supports pre-registration; MADEIRA AI has not yet imported the individual business list from this JavaScript-rendered portal.',
last_checked_at=now(),is_active=true
where id='ponta-do-sol-business-directory';
